-- Cierra sucursales en las RPC nativas; preserva firmas, ACL y motores.
-- No modifica filas; sólo MCP tras gate acotado. No usa SQLSTATE 40001.
SET LOCAL lock_timeout='1s';
SET LOCAL statement_timeout='4s';
DO $crm_call_branch_delta$
DECLARE v_item jsonb; v_patch jsonb; v_oid oid; v_source text; v_definition text; v_metadata jsonb; v_current jsonb;
BEGIN
 FOR v_item IN SELECT value FROM jsonb_array_elements($crm_call_branch_manifest$[{"signature":"public.fn_crm_disponer_llamada(integer,uuid,text,jsonb)","before":"9c05b0939261d6947aa00f653c43869f","after":"d350a2461a311bbbad390beb2df756fc","acl":"{postgres=X/postgres,authenticated=X/postgres}","config":["search_path=public, pg_temp"],"owner":"postgres","security_definer":true,"patches":[{"before":"  IF v_call.user_id IS DISTINCT FROM v_actor AND NOT public.fn_crm_tiene_permiso(p_org,'crm.activities.edit_any') THEN\n    RAISE EXCEPTION 'llamada_no_es_propia' USING ERRCODE='42501'; END IF;","after":"  IF v_call.user_id IS DISTINCT FROM v_actor AND NOT public.fn_crm_tiene_permiso(p_org,'crm.activities.edit_any') THEN\n    RAISE EXCEPTION 'llamada_no_es_propia' USING ERRCODE='42501'; END IF;\n  -- El núcleo privado PHONE comparte el alcance de tenant/sucursal.\n  PERFORM public.fn_phone_assert_call_scope_core(p_org,p_call);"}]},{"signature":"public.fn_crm_vincular_llamada(integer,uuid,text,jsonb)","before":"2dea24acc694be4888da41f910a8ef09","after":"d26a992174382fe47ee25de954f860d0","acl":"{postgres=X/postgres,authenticated=X/postgres}","config":["search_path=public, pg_temp"],"owner":"postgres","security_definer":true,"patches":[{"before":"  IF v_call.user_id IS DISTINCT FROM v_actor AND NOT public.fn_crm_tiene_permiso(p_org,'crm.activities.edit_any') THEN\n    RAISE EXCEPTION 'llamada_no_es_propia' USING ERRCODE='42501'; END IF;","after":"  IF v_call.user_id IS DISTINCT FROM v_actor AND NOT public.fn_crm_tiene_permiso(p_org,'crm.activities.edit_any') THEN\n    RAISE EXCEPTION 'llamada_no_es_propia' USING ERRCODE='42501'; END IF;\n  -- El núcleo privado PHONE comparte el alcance de tenant/sucursal.\n  PERFORM public.fn_phone_assert_call_scope_core(p_org,p_call);"},{"before":"    IF NOT FOUND THEN RAISE EXCEPTION 'oportunidad_no_encontrada' USING ERRCODE='P0002'; END IF;","after":"    IF NOT FOUND THEN RAISE EXCEPTION 'oportunidad_no_encontrada' USING ERRCODE='P0002'; END IF;\n    IF NOT EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=v_opportunity AND o.organization_id=p_org\n      AND (o.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=o.branch_id AND b.organization_id=p_org))\n      AND public.app_branch_access(o.branch_id::integer)) THEN\n      RAISE EXCEPTION 'sucursal_sin_permiso' USING ERRCODE='42501'; END IF;"},{"before":"    IF NOT FOUND THEN RAISE EXCEPTION 'cliente_no_encontrado' USING ERRCODE='P0002'; END IF;","after":"    IF NOT FOUND THEN RAISE EXCEPTION 'cliente_no_encontrado' USING ERRCODE='P0002'; END IF;\n    IF NOT EXISTS(SELECT 1 FROM public.customers c WHERE c.id=v_customer AND c.organization_id=p_org\n      AND (c.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=c.branch_id AND b.organization_id=p_org))\n      AND public.app_branch_access(c.branch_id::integer)) THEN\n      RAISE EXCEPTION 'sucursal_sin_permiso' USING ERRCODE='42501'; END IF;"},{"before":"    WHERE id=p_call AND organization_id=p_org RETURNING * INTO v_call;\n  v_sync:=public.fn_crm_sync_llamada_core(p_org,p_call);","after":"    WHERE id=p_call AND organization_id=p_org RETURNING * INTO v_call;\n  -- Valida también referencias recién creadas dentro de esta misma transacción.\n  PERFORM public.fn_phone_assert_call_scope_core(p_org,p_call);\n  v_sync:=public.fn_crm_sync_llamada_core(p_org,p_call);"}]},{"signature":"public.fn_crm_crear_llamada(integer,jsonb)","before":"21743883b30fd74b2a889b013e54c5be","after":"0e1c215728752de9776d4bb52eeec41b","acl":"{postgres=X/postgres,authenticated=X/postgres}","config":["search_path=public, pg_temp"],"owner":"postgres","security_definer":true,"patches":[{"before":"    IF NOT FOUND THEN RAISE EXCEPTION 'oportunidad_no_encontrada' USING ERRCODE='P0002'; END IF;","after":"    IF NOT FOUND THEN RAISE EXCEPTION 'oportunidad_no_encontrada' USING ERRCODE='P0002'; END IF;\n    IF NOT EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=v_row.opportunity_id AND o.organization_id=p_org\n      AND (o.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=o.branch_id AND b.organization_id=p_org))\n      AND public.app_branch_access(o.branch_id::integer)) THEN\n      RAISE EXCEPTION 'sucursal_sin_permiso' USING ERRCODE='42501'; END IF;"},{"before":"    IF NOT FOUND THEN RAISE EXCEPTION 'cliente_no_encontrado' USING ERRCODE='P0002'; END IF;","after":"    IF NOT FOUND THEN RAISE EXCEPTION 'cliente_no_encontrado' USING ERRCODE='P0002'; END IF;\n    IF NOT EXISTS(SELECT 1 FROM public.customers c WHERE c.id=v_customer AND c.organization_id=p_org\n      AND (c.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=c.branch_id AND b.organization_id=p_org))\n      AND public.app_branch_access(c.branch_id::integer)) THEN\n      RAISE EXCEPTION 'sucursal_sin_permiso' USING ERRCODE='42501'; END IF;"},{"before":"    INTO v_call USING v_data;\n  PERFORM public.fn_crm_sync_llamada_core(p_org,v_call.id);","after":"    INTO v_call USING v_data;\n  PERFORM public.fn_phone_assert_call_scope_core(p_org,v_call.id);\n  PERFORM public.fn_crm_sync_llamada_core(p_org,v_call.id);"}]},{"signature":"public.fn_phone_assert_call_scope_core(integer,uuid)","before":"2336f1f9756da0912195a814676627ae","after":"475b735c4d46b89955435574601195de","acl":"{postgres=X/postgres}","config":["search_path=public, pg_temp"],"owner":"postgres","security_definer":true,"patches":[{"before":"    AND public.app_branch_access(c.branch_id::integer)))","after":"    AND (c.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=c.branch_id AND b.organization_id=p_org))\n    AND public.app_branch_access(c.branch_id::integer)))"},{"before":"    AND o.customer_id IS NOT DISTINCT FROM v_call.customer_id AND public.app_branch_access(o.branch_id::integer)))","after":"    AND (o.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=o.branch_id AND b.organization_id=p_org))\n    AND o.customer_id IS NOT DISTINCT FROM v_call.customer_id AND public.app_branch_access(o.branch_id::integer)))"}]},{"signature":"public.crm_calls_list(integer,jsonb)","before":"e98a3b20121ffaa1f808d324a42f26ce","after":"2645f28d3f4335dca1af203e17ae963b","acl":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}","config":["search_path=public, pg_temp"],"owner":"postgres","security_definer":true,"patches":[{"before":"      and (v_user is null or c.user_id=v_user)","after":"      and (v_user is null or c.user_id=v_user)\n      -- La RPC es SECURITY DEFINER: replica el alcance restrictivo del listado.\n      and (auth.uid() is null or (\n        (c.customer_id is null or exists(select 1 from public.customers cu where cu.id=c.customer_id and cu.organization_id=p_org\n          and (cu.branch_id is null or exists(select 1 from public.branches b where b.id=cu.branch_id and b.organization_id=p_org))\n          and public.app_branch_access(cu.branch_id::integer)))\n        and (c.opportunity_id is null or exists(select 1 from public.opportunities o where o.id=c.opportunity_id and o.organization_id=p_org\n          and o.customer_id is not distinct from c.customer_id\n          and (o.branch_id is null or exists(select 1 from public.branches b where b.id=o.branch_id and b.organization_id=p_org))\n          and public.app_branch_access(o.branch_id::integer)))\n      ))"},{"before":"from public.call_analyses a where a.call_id=c.id and a.organization_id=p_org order by a.created_at desc,a.id limit 1)","after":"from public.call_analyses a where a.call_id=c.id and a.organization_id=p_org\n        and (a.transcript_id is null or exists(select 1 from public.call_transcripts t where t.id=a.transcript_id and t.organization_id=a.organization_id and t.call_id=a.call_id))\n        order by a.created_at desc,a.id limit 1)"}]}]$crm_call_branch_manifest$::jsonb) LOOP
  v_oid:=to_regprocedure(v_item->>'signature');
  IF v_oid IS NULL THEN RAISE EXCEPTION 'rpc_llamadas_ausente' USING ERRCODE='P0001'; END IF;
  SELECT p.prosrc,(to_jsonb(p)-'prosrc'-'proargdefaults') || jsonb_build_object('function_arguments',pg_get_function_arguments(p.oid),'default_ast_without_locations',regexp_replace(p.proargdefaults::text,':location -?[0-9]+',':location <offset>','g')) INTO v_source,v_metadata FROM pg_proc p WHERE p.oid=v_oid;
  IF (SELECT p.proacl::text FROM pg_proc p WHERE p.oid=v_oid) IS DISTINCT FROM v_item->>'acl'
   OR (SELECT to_jsonb(p.proconfig) FROM pg_proc p WHERE p.oid=v_oid) IS DISTINCT FROM v_item->'config'
   OR (SELECT pg_get_userbyid(p.proowner) FROM pg_proc p WHERE p.oid=v_oid) IS DISTINCT FROM v_item->>'owner'
   OR (SELECT p.prosecdef FROM pg_proc p WHERE p.oid=v_oid) IS DISTINCT FROM (v_item->>'security_definer')::boolean THEN
   RAISE EXCEPTION 'contrato_rpc_llamadas_modificado' USING ERRCODE='P0001'; END IF;
  IF md5(v_source)=v_item->>'after' THEN CONTINUE; END IF;
  IF md5(v_source) IS DISTINCT FROM v_item->>'before' THEN
   RAISE EXCEPTION 'fuente_rpc_llamadas_modificada' USING ERRCODE='P0001'; END IF;
  v_definition:=pg_get_functiondef(v_oid);
  FOR v_patch IN SELECT value FROM jsonb_array_elements(v_item->'patches') LOOP
   IF length(v_definition)-length(replace(v_definition,v_patch->>'before',''))<>length(v_patch->>'before') THEN
    RAISE EXCEPTION 'delta_rpc_llamadas_ambiguo' USING ERRCODE='P0001'; END IF;
   v_definition:=replace(v_definition,v_patch->>'before',v_patch->>'after');
  END LOOP;
  EXECUTE v_definition;
  SELECT p.prosrc,(to_jsonb(p)-'prosrc'-'proargdefaults') || jsonb_build_object('function_arguments',pg_get_function_arguments(p.oid),'default_ast_without_locations',regexp_replace(p.proargdefaults::text,':location -?[0-9]+',':location <offset>','g')) INTO v_source,v_current FROM pg_proc p WHERE p.oid=v_oid;
  IF md5(v_source) IS DISTINCT FROM v_item->>'after' OR v_metadata IS DISTINCT FROM v_current THEN
   RAISE EXCEPTION 'contrato_rpc_llamadas_no_conservado' USING ERRCODE='P0001'; END IF;
 END LOOP;
END;
$crm_call_branch_delta$;
